using System.ComponentModel;
using System.Diagnostics;
using System.IO.Compression;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;

namespace OverwatchDecoder.Observer;

/// <summary>Independent portable tests. All bytes are generated by an in-process fake.</summary>
public static class RecordingTests
{
    private sealed class FakeTimer : PreciseWait.IOneShotTimer
    {
        private readonly AutoResetEvent signal = new(false);
        public WaitHandle Signal => signal;
        public int Arms { get; private set; }
        public int Cancels { get; private set; }
        public int Disposals { get; private set; }
        public long DueTime { get; private set; }
        public Action<FakeTimer>? OnArm { get; init; }
        public void Arm(long dueTime)
        { Arms++; DueTime = dueTime; OnArm?.Invoke(this); }
        public void Fire() => signal.Set();
        public void Cancel() { Cancels++; }
        public void Dispose() { Disposals++; signal.Dispose(); }
    }

    private sealed class FakeMemory : IMemorySource
    {
        public TargetIdentity Identity { get; set; } = new(123, "fixture.exe", "private-test-path", 1, new string('a', 64), "x64");
        public int Calls { get; private set; }
        public int DelayMs { get; init; }
        public int StartupDelayMs { get; init; }
        public bool StartupPauseInjected { get; private set; }
        private int aliveChecks;
        public Func<int, string?> Failure { get; init; } = _ => null;
        public Action<int>? AfterRead { get; set; }
        public string? AliveFailure { get; set; }
        public IEnumerable<MemoryRegion> Regions() => [new(4096, 8192, 0x1000, 0x04, 0x20000)];
        public byte[] Read(ulong address, int size)
        {
            Calls++;
            if (DelayMs != 0) Thread.Sleep(DelayMs);
            string? failure = Failure(Calls);
            if (failure is not null) throw new ObservationException(failure, "Synthetic page failure.");
            var bytes = new byte[size];
            BitConverter.GetBytes(Calls).CopyTo(bytes, 0);
            BitConverter.GetBytes(99).CopyTo(bytes, 4);
            AfterRead?.Invoke(Calls);
            return bytes;
        }
        public void EnsureAlive()
        {
            if (AliveFailure is not null) throw new ObservationException(AliveFailure, "Synthetic target stopped.");
            // The first check loads the input identity; the next is inside the first sampling batch.
            if (++aliveChecks == 2 && StartupDelayMs > 0)
            { StartupPauseInjected = true; Thread.Sleep(StartupDelayMs); }
        }
        public void Dispose() { }
    }

    public static int Run()
    {
        string phase = "scheduler";
        try { return RunChecks(value => phase = value); }
        catch (ObservationException e)
        { throw new ObservationException("self_test_failed", $"recording phase={phase}; {e.Code}: {e.Message}", e.NativeCode); }
        catch (Exception e)
        {
            // Method/type names provide useful context without leaking temporary filesystem paths.
            var method = new StackTrace(e).GetFrame(0)?.GetMethod();
            throw new ObservationException("self_test_failed", $"recording phase={phase}; unexpected {e.GetType().Name}; " +
                $"method={method?.DeclaringType?.FullName}.{method?.Name}");
        }
    }

    private static int RunChecks(Action<string> setPhase)
    {
        int assertions = 0;
        void Check(bool condition, string name)
        {
            if (!condition) throw new ObservationException("self_test_failed", "recording:" + name);
            assertions++;
        }
        void Throws(Action action, string code)
        {
            try { action(); }
            catch (ObservationException e) { Check(e.Code == code, "error " + code + ", received " + e.Code); return; }
            throw new ObservationException("self_test_failed", "recording:expected " + code);
        }
        TestPreciseWait(Check, setPhase);
        string root = Path.Combine(Path.GetTempPath(), "overwatch-decoder-recording-test-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(root);
        try
        {
            string Input(string name, FakeMemory source, ulong[]? addresses = null, string type = "i32", int? declared = null)
            {
                setPhase("input/" + name);
                string directory = Path.Combine(root, name);
                Directory.CreateDirectory(directory);
                string[] lines = (addresses ?? [4096UL, 4100UL]).Select(address => JsonSerializer.Serialize(new
                { address, bytes_hex = type == "f64" ? "0000000000000000" : "00000000", sampled_ticks = 7L })).ToArray();
                byte[] bytes = Encoding.UTF8.GetBytes(string.Join("\n", lines) + "\n");
                File.WriteAllBytes(Path.Combine(directory, "candidates.jsonl"), bytes);
                File.WriteAllText(Path.Combine(directory, "manifest.json"), JsonSerializer.Serialize(new
                {
                    schema = "overwatch-decoder.memory-candidates/1", target = Snapshots.PublicIdentity(source.Identity), type,
                    candidates = declared ?? lines.Length, candidates_sha256 = Convert.ToHexStringLower(SHA256.HashData(bytes))
                }));
                return directory;
            }
            JsonElement Record(FakeMemory source, string input, string name, int ms = 10, int durationMs = 30_000,
                CancellationToken token = default, ResearchRecorder.Limits? limits = null)
            {
                setPhase("record/" + name);
                object result = ResearchRecorder.RecordBounded(source, input, Path.Combine(root, name), ms,
                    TimeSpan.FromMilliseconds(durationMs), token, limits ?? new());
                return JsonSerializer.SerializeToElement(result);
            }
            JsonElement RecordThroughReads(FakeMemory source, string input, string name, int reads, int ms = 10)
            {
                // Completion is driven by observed fake reads. Duration is only a generous failure watchdog.
                using var cancellation = new CancellationTokenSource();
                int expected = source.Calls + reads;
                Action<int>? prior = source.AfterRead;
                source.AfterRead = count => { prior?.Invoke(count); if (count >= expected) cancellation.Cancel(); };
                JsonElement result;
                try { result = Record(source, input, name, ms: ms, token: cancellation.Token); }
                finally { source.AfterRead = prior; }
                Check(source.Calls == expected, $"{name}: expected {expected} reads, actual {source.Calls}; stop={result.GetProperty("stop_reason").GetString()}");
                Check(result.GetProperty("stop_reason").GetString() == "cancelled", name + ": read-driven cancellation ended recording");
                return result;
            }
            List<JsonElement> Samples(string name, int expectedCount)
            {
                setPhase("samples/" + name);
                using var file = File.OpenRead(Path.Combine(root, name, "samples.jsonl.gz"));
                using var gzip = new GZipStream(file, CompressionMode.Decompress);
                using var reader = new StreamReader(gzip);
                var records = new List<JsonElement>();
                while (reader.ReadLine() is { } line)
                { using var doc = JsonDocument.Parse(line); records.Add(doc.RootElement.Clone()); }
                Check(records.Count == expectedCount, $"{name}: expected {expectedCount} stored samples, actual {records.Count}");
                return records;
            }
            JsonElement OnlyPage(JsonElement frame, string name)
            {
                var pages = frame.GetProperty("pages");
                Check(pages.GetArrayLength() == 1, name + ": exactly one page per frame");
                return pages[0];
            }

            var changing = new FakeMemory { Failure = call => call == 2 ? "unreadable_range" : null };
            string input = Input("changing-input", changing);
            var result = RecordThroughReads(changing, input, "changing", 4);
            var samples = Samples("changing", 4);
            Check(samples.Count == 4 && changing.Calls == 4, "one page read for two nearby candidates");
            Check(samples[0].GetProperty("kind").GetString() == "keyframe", "first frame is keyframe");
            var state = new Dictionary<int, string?>();
            for (int n = 0; n < samples.Count; n++)
            {
                var frame = samples[n];
                if (frame.GetProperty("kind").GetString() == "keyframe") state.Clear();
                var page = OnlyPage(frame, "changing");
                foreach (var change in page.GetProperty("changes").EnumerateArray())
                {
                    bool available = change.GetProperty("available").GetBoolean();
                    state[change.GetProperty("id").GetInt32()] = available ? change.GetProperty("bytes_hex").GetString() : null;
                }
                Check(state.Count == 2 && state.ContainsKey(0) && state.ContainsKey(1), "all candidates reconstruct");
                Check(state[0] == (n == 1 ? null : Convert.ToHexStringLower(BitConverter.GetBytes(n + 1))), "changing value or explicit unknown");
                Check(state[1] == (n == 1 ? null : Convert.ToHexStringLower(BitConverter.GetBytes(99))), "stable value recovers from unknown");
                Check(page.GetProperty("end_ticks").GetInt64() >= page.GetProperty("start_ticks").GetInt64(), "read timestamp order");
                Check(frame.GetProperty("end_ticks").GetInt64() >= page.GetProperty("end_ticks").GetInt64(), "batch bounds page timestamp");
            }
            Check(samples[3].GetProperty("pages")[0].GetProperty("changes").GetArrayLength() == 1, "delta omits unchanged known value");
            Check(result.GetProperty("failed_pages").GetInt64() == 1, "page faults counted");
            Check(result.GetProperty("stop_reason").GetString() == "cancelled" && !result.GetProperty("complete").GetBoolean(), "cancellation preserves partial recording");
            Check(!result.GetProperty("public_state_eligible").GetBoolean() && !result.GetProperty("runtime_semantics_validated").GetBoolean(), "research only");
            Check(!result.GetRawText().Contains("private-test-path", StringComparison.Ordinal), "summary redacts source path");
            Check(result.GetProperty("batches").GetInt64() == samples.Count, "manifest agrees with data");
            Check(result.GetProperty("samples_sha256").GetString() == Digest(Path.Combine(root, "changing", "samples.jsonl.gz")), "sample digest");
            Check(result.GetProperty("dictionary_sha256").GetString() == Digest(Path.Combine(root, "changing", "dictionary.jsonl")), "dictionary digest");
            Throws(() => Record(changing, input, "changing"), "output_exists");
            Throws(() => Record(changing, input, "bad-interval", ms: 1), "invalid_arguments");
            Throws(() => Record(changing, input, "bad-duration", durationMs: 0), "invalid_arguments");
            Throws(() => ResearchRecorder.Record(changing, input, Path.Combine(root, "long"), 10, TimeSpan.FromHours(11), default), "invalid_arguments");

            var mismatch = new FakeMemory();
            string mismatchInput = Input("mismatch-input", mismatch);
            mismatch.Identity = mismatch.Identity with { CreationFileTime = 2 };
            Throws(() => Record(mismatch, mismatchInput, "mismatch"), "identity_mismatch");
            Check(!Directory.Exists(Path.Combine(root, "mismatch")), "identity checked before output creation");
            string corruptInput = Input("corrupt-input", new());
            File.AppendAllText(Path.Combine(corruptInput, "candidates.jsonl"), " ");
            Throws(() => Record(new(), corruptInput, "corrupt"), "digest_mismatch");
            Throws(() => Record(new(), Input("count-input", new(), declared: 3), "count"), "invalid_manifest");
            Throws(() => Record(new(), Input("unsorted-input", new(), [4100, 4096]), "unsorted"), "invalid_manifest");
            Throws(() => Record(new(), Input("alignment-input", new(), [4097]), "alignment"), "invalid_manifest");
            Throws(() => Record(new(), Input("type-input", new(), type: "unknown"), "type"), "invalid_manifest");
            Throws(() => Record(new(), Input("empty-input", new(), [], declared: 0), "empty"), "candidate_limit");
            Throws(() => Record(new(), Input("limit-input", new(), declared: ResearchRecorder.MaximumCandidates + 1), "limit"), "candidate_limit");
            ulong[] addresses = Enumerable.Range(1, ResearchRecorder.MaximumPages + 1).Select(n => (ulong)n * 4096).ToArray();
            Throws(() => Record(new(), Input("page-limit-input", new(), addresses), "page-limit"), "page_limit");
            string largeInput = Input("large-input", new());
            using (var largeManifest = new FileStream(Path.Combine(largeInput, "manifest.json"), FileMode.Open))
                largeManifest.SetLength(1024 * 1024 + 1);
            Throws(() => Record(new(), largeInput, "large"), "candidate_file_limit");

            foreach (string error in new[] { "permission_denied", "process_exited", "identity_mismatch" })
            {
                var failed = new FakeMemory { Failure = _ => error };
                var stopped = Record(failed, Input(error + "-input", failed, [4096, 8192]), error);
                Check(stopped.GetProperty("stop_reason").GetString() == error && failed.Calls == 1, "fatal error stops additional reads " + error);
                var frame = Samples(error, 1).Single();
                Check(frame.GetProperty("pages").GetArrayLength() == 2, "fatal error covers remaining pages");
                Check(frame.GetProperty("pages")[1].GetProperty("error").GetString() == "not_sampled", "remaining page explicitly unknown");
                Check(frame.GetProperty("pages")[1].GetProperty("changes").GetArrayLength() == 1, "unknown page includes its one candidate");
                Check(frame.GetProperty("pages")[1].GetProperty("changes")[0].GetProperty("bytes_hex").ValueKind == JsonValueKind.Null, "unknown is explicit null");
            }
            var identityDuringRead = new FakeMemory();
            identityDuringRead.AfterRead = _ => identityDuringRead.Identity = identityDuringRead.Identity with { Pid = 999 };
            var changedIdentity = Record(identityDuringRead, Input("identity-read-input", identityDuringRead), "identity-read");
            Check(changedIdentity.GetProperty("stop_reason").GetString() == "identity_mismatch", "identity checked after read");
            Check(!OnlyPage(Samples("identity-read", 1)[0], "identity-read").GetProperty("ok").GetBoolean(), "changed target bytes are discarded");

            var slow = new FakeMemory { DelayMs = 35 };
            var slowResult = RecordThroughReads(slow, Input("slow-input", slow), "slow", 3);
            var slowFrames = Samples("slow", 3);
            Check(slowFrames.Count == 3 && slowResult.GetProperty("skipped_intervals").GetInt64() >= 4, "slow reads skip scheduling slots");
            Check(slowFrames[1].GetProperty("scheduled_slot").GetInt64() >= 3, "no queued catchup reads");
            Check(slowResult.GetProperty("maximum_batch_ms").GetDouble() >= 30, "actual slow duration measured");

            foreach (var (name, limits, reason) in new[]
            {
                ("read-cap", new ResearchRecorder.Limits(ReadBytes: 1), "read_byte_limit"),
                ("json-cap", new ResearchRecorder.Limits(JsonBytes: 1), "json_byte_limit"),
                ("disk-cap", new ResearchRecorder.Limits(CompressedBytes: 1), "compressed_byte_limit")
            })
            {
                var bounded = new FakeMemory();
                var boundedResult = Record(bounded, input, name, limits: limits);
                Check(boundedResult.GetProperty("stop_reason").GetString() == reason && !boundedResult.GetProperty("complete").GetBoolean(), "limit is an explicit incomplete stop " + name);
                Check(boundedResult.GetProperty("attempted_read_bytes").GetInt64() <= limits.ReadBytes, "read cap honored");
                Check(boundedResult.GetProperty("compressed_bytes").GetInt64() <= limits.CompressedBytes, "output cap honored");
                Check(boundedResult.GetProperty("uncompressed_json_bytes").GetInt64() <= limits.JsonBytes, "json cap honored");
            }
            var preCancelled = Record(new(), input, "pre-cancelled", token: new CancellationToken(true));
            Check(preCancelled.GetProperty("batches").GetInt64() == 0 && preCancelled.GetProperty("stop_reason").GetString() == "cancelled", "pre-cancelled run is preserved without reads");
            var complete = Record(new(), input, "complete", ms: 10, durationMs: 35);
            Check(complete.GetProperty("complete").GetBoolean() && complete.GetProperty("stop_reason").GetString() == "duration_elapsed", "bounded duration completes normally");
            Check(complete.GetProperty("monotonic_origin_ticks").GetInt64() >= complete.GetProperty("utc_origin_before_ticks").GetInt64() &&
                complete.GetProperty("monotonic_frequency").GetInt64() == Stopwatch.Frequency, "UTC origin is bracketed and frequency explicit");
            Check(complete.GetProperty("scheduler").GetProperty("backend").GetString() is
                "managed_wait_handle" or "windows_high_resolution_waitable_timer", "selected scheduler is recorded");
            Check(!complete.GetProperty("scheduler").GetProperty("global_timer_resolution_changed").GetBoolean() &&
                !complete.GetProperty("scheduler").GetProperty("hard_realtime").GetBoolean(), "scheduler claims remain bounded");
            var doubleSource = new FakeMemory { StartupDelayMs = 75, DelayMs = 75 };
            var doubleResult = RecordThroughReads(doubleSource, Input("double-input", doubleSource, [4096], "f64"), "double", 1);
            var doublePage = OnlyPage(Samples("double", 1)[0], "double");
            var doubleChanges = doublePage.GetProperty("changes");
            Check(doublePage.GetProperty("ok").GetBoolean() && doubleChanges.GetArrayLength() == 1, "f64 sample contains one readable candidate");
            string? doubleBytes = doubleChanges[0].GetProperty("bytes_hex").GetString();
            Check(doubleResult.GetProperty("type").GetString() == "f64" && doubleBytes is { Length: 16 }, "eight-byte candidate capture");
            Check(doubleBytes == Convert.ToHexStringLower(BitConverter.GetBytes(1).Concat(BitConverter.GetBytes(99)).ToArray()),
                "eight-byte candidate exactly matches both fixture words");
            Check(doubleSource.StartupPauseInjected && doubleResult.GetProperty("elapsed_ms").GetDouble() >= 100,
                "f64 capture survives a deliberate startup pause and slow read longer than the former 30ms window");
            var periodicSource = new FakeMemory
            {
                // Make the next batch start beyond the keyframe interval, then stop on its completed read.
                AfterRead = count => { if (count == 1) Thread.Sleep(1100); }
            };
            RecordThroughReads(periodicSource, input, "periodic", 2);
            var periodicFrames = Samples("periodic", 2);
            Check(periodicFrames.All(frame => frame.GetProperty("kind").GetString() == "keyframe"),
                "both frames are independent keyframes after the controlled slow read");
            foreach (var frame in periodicFrames)
                Check(OnlyPage(frame, "periodic").GetProperty("changes").GetArrayLength() == 2,
                    "periodic keyframe repeats both the changing and unchanged candidates");
        }
        finally { Directory.Delete(root, true); }
        return assertions;
    }

    private static string Digest(string path)
    { using var file = File.OpenRead(path); return Convert.ToHexStringLower(SHA256.HashData(file)); }

    private static void TestPreciseWait(Action<bool, string> check, Action<string> setPhase)
    {
        setPhase("scheduler/conversion");
        check(PreciseWait.RelativeDueTime100ns(1, 1_000_000_000) == -1, "sub-100ns wait rounds up");
        check(PreciseWait.RelativeDueTime100ns(10_000_000, 1_000_000_000) == -100_000, "10ms due time is relative in 100ns units");
        check(PreciseWait.RelativeDueTime100ns(long.MaxValue, 1) == -1_000_000, "distant wait is bounded without overflow");

        using (var cancellation = new CancellationTokenSource())
        using (var armed = new ManualResetEventSlim())
        {
            setPhase("scheduler/cancellation");
            var timer = new FakeTimer { OnArm = _ => armed.Set() };
            var scheduler = new PreciseWait(cancellation.Token, timer);
            Task waiter = Task.Run(() => scheduler.WaitUntil(Stopwatch.GetTimestamp() + 5 * Stopwatch.Frequency));
            try
            {
                check(armed.Wait(TimeSpan.FromSeconds(2)), "timer armed before cancellation");
                cancellation.Cancel();
                check(waiter.Wait(TimeSpan.FromSeconds(2)), "cancellation wakes timer wait before its deadline");
                check(timer.Arms == 1 && timer.Cancels >= 1, "pending timer cancelled after cancellation signal");
                check(timer.DueTime == -1_000_000, "long wait uses bounded one-shot timer");
            }
            finally
            {
                cancellation.Cancel();
                waiter.Wait(TimeSpan.FromSeconds(2));
                scheduler.Dispose();
            }
            scheduler.Dispose();
            check(timer.Disposals == 1, "owned timer disposed exactly once");
            // The scheduler does not own the token's wait handle.
            check(cancellation.Token.WaitHandle.WaitOne(0), "caller cancellation handle remains usable");
            try { scheduler.WaitUntil(Stopwatch.GetTimestamp()); check(false, "disposed scheduler rejects waiting"); }
            catch (ObjectDisposedException) { check(true, "disposed scheduler rejects waiting"); }
        }

        using (var cancelled = new CancellationTokenSource())
        {
            setPhase("scheduler/pre-cancelled");
            cancelled.Cancel();
            var timer = new FakeTimer();
            using var scheduler = new PreciseWait(cancelled.Token, timer);
            scheduler.WaitUntil(Stopwatch.GetTimestamp() + Stopwatch.Frequency);
            check(timer.Arms == 0, "pre-cancelled wait never arms a timer");
        }
        using (var cancellation = new CancellationTokenSource())
        {
            setPhase("scheduler/early-signal");
            var timer = new FakeTimer
            { OnArm = current => { if (current.Arms == 1) current.Fire(); else cancellation.Cancel(); } };
            using var scheduler = new PreciseWait(cancellation.Token, timer);
            scheduler.WaitUntil(Stopwatch.GetTimestamp() + Stopwatch.Frequency);
            check(timer.Arms == 2, "early timer signal rechecks monotonic deadline");
        }
        {
            setPhase("scheduler/operation-fallback");
            var timer = new FakeTimer { OnArm = _ => throw new Win32Exception(87) };
            using var scheduler = new PreciseWait(CancellationToken.None, timer);
            long target = Stopwatch.GetTimestamp() + Stopwatch.Frequency / 5;
            scheduler.WaitUntil(target);
            var details = JsonSerializer.SerializeToElement(scheduler.Diagnostics());
            check(Stopwatch.GetTimestamp() >= target, "fallback respects monotonic deadline");
            check(timer.Arms == 1 && timer.Disposals == 1, "failed native backend closes handle and is not retried");
            check(details.GetProperty("backend").GetString() == "managed_wait_handle" &&
                details.GetProperty("initial_backend").GetString() == "windows_high_resolution_waitable_timer", "backend transition reported");
            check(details.GetProperty("fallback_reason").GetString() == "timer_operation_failed" &&
                details.GetProperty("fallback_native_code").GetInt32() == 87 &&
                details.GetProperty("fallback_at_ticks").GetInt64() > 0, "fallback preserves native failure evidence");
            check(details.GetProperty("managed_waits").GetInt64() > 0, "fallback performs actual managed waits");
        }
        using (var scheduler = new PreciseWait(CancellationToken.None, null, "create_waitable_timer_failed", 50))
        {
            setPhase("scheduler/creation-fallback");
            var details = JsonSerializer.SerializeToElement(scheduler.Diagnostics());
            check(details.GetProperty("backend").GetString() == "managed_wait_handle" &&
                details.GetProperty("fallback_reason").GetString() == "create_waitable_timer_failed" &&
                details.GetProperty("fallback_native_code").GetInt32() == 50, "creation fallback is explicit");
        }
        {
            setPhase("scheduler/timeout-fallback");
            var timer = new FakeTimer(); // Deliberately never signals: exercise the bounded malfunction guard.
            using var scheduler = new PreciseWait(CancellationToken.None, timer);
            scheduler.WaitUntil(Stopwatch.GetTimestamp() + Stopwatch.Frequency / 4);
            var details = JsonSerializer.SerializeToElement(scheduler.Diagnostics());
            check(timer.Arms == 1 && timer.Disposals == 1, "non-signalling timer is closed after bounded wait");
            check(details.GetProperty("fallback_reason").GetString() == "timer_wait_timeout" &&
                details.GetProperty("backend").GetString() == "managed_wait_handle", "timer timeout fallback is explicit");
        }
        using (var scheduler = PreciseWait.Create(CancellationToken.None))
        {
            setPhase("scheduler/platform");
            long target = Stopwatch.GetTimestamp() + Stopwatch.Frequency / 50;
            scheduler.WaitUntil(target);
            check(Stopwatch.GetTimestamp() >= target, "platform scheduler does not return before deadline");
            var details = JsonSerializer.SerializeToElement(scheduler.Diagnostics());
            if (!OperatingSystem.IsWindows())
                check(details.GetProperty("backend").GetString() == "managed_wait_handle" &&
                    details.GetProperty("fallback_reason").GetString() == "not_windows", "portable backend reported without Windows calls");
            else
                check(details.GetProperty("high_resolution_waits").GetInt64() > 0 ||
                    details.GetProperty("fallback_reason").ValueKind == JsonValueKind.String, "Windows timer used or fallback explained");
        }
    }
}
